let issues = 0;
const merged = {};
for (const [exId, items] of Object.entries(data)) {
  merged[exId] = { items: {}, translation: { questions: fullText[exId] || {} } };
  for (const [pos, d] of Object.entries(items)) {
    merged[exId].items[pos] = {
      keyword: d.kw,
      evidence_text: d.ev,
      evidence_translation: null,
      explanation_correct: d.correct,
      explanation_wrong: d.wrong,
    };
  }
}

writeFileSync("C:/Users/asus/AuraLingovia/scripts/learning-aids/lesen_t1_batch1.json", JSON.stringify(merged));
console.log("Wrote lesen_t1_batch1.json for", Object.keys(merged).length, "exercises");

for (const [exId, aids] of Object.entries(merged)) {
  for (const [pos, item] of Object.entries(aids.items)) {
    if (!item.explanation_correct || item.explanation_correct.length < 30) { console.error("bad correct", exId, pos); issues++; }
    if (!aids.translation.questions[pos]) { console.error("missing translation", exId, pos); issues++; }
  }
}
console.log("issues:", issues);
